module div_8bit
    (
      input clk,
      input rstn,
      input sign,
      input [7:0] dividend,
      input [7:0] divisor,
      input opn_valid,
      input res_ready,
      output reg res_valid,
      output reg [15:0] result
    );

    reg [8:0] dividend_e ;
    reg [8:0] divisor_e  ;
    reg [15:0] sr;
    reg [3:0] cnt;
    reg [8:0] neg_divisor;
    wire [8:0] sub_result;
    wire [9:0] all_sub_result;
    reg [8:0] quotient;
    wire [8:0] remainder;
    reg [8:0] quotient_shift;
    reg [8:0] dividend_abs;
    reg [8:0] final_remainder;
    reg [8:0] final_quotient;
    wire is_final_quotient_sign;
    reg start_cnt;

    assign neg_divisor = (sign && divisor_e[8]) ? -divisor_e : divisor_e;
    assign sub_result = all_sub_result[8:0];
    assign all_sub_result = {neg_divisor, 2'b0} - {1'b0, dividend_e};
    assign quotient_shift = sr[15:9];
    assign dividend_abs = (sign && dividend[7]) ? -dividend : dividend;
    assign final_remainder = (sign && (dividend_e >= divisor_e)) ? -sub_result : sub_result;
    assign final_quotient = (sign && (dividend_e >= divisor_e)) ? -quotient : quotient;
    assign is_final_quotient_sign = sign && (dividend_e >= divisor_e);
    assign res_valid = (cnt == 4'd8) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge rstn) begin
        if(!rstn)begin
            start_cnt <= 1'b0;
        end
        else if(opn_valid && !res_valid && !start_cnt)begin
            start_cnt <= 1'b1;
            dividend_e <= {{1{sign && dividend[7]}}, dividend};
            divisor_e <= {divisor, 1'b0};
        end
        else if(start_cnt && !res_valid && !res_ready)begin
            start_cnt <= 1'b1;
            sr <= {neg_divisor, 2'b0};
            quotient <= 8'b0;
        end
        else if(!start_cnt && !res_valid && !res_ready)begin
            start_cnt <= 1'b0;
            sr <= {1'b0, sr[15:1]};
            quotient <= {quotient[7:0], 1'b0};
        end
    end

    always @(posedge clk or negedge rstn) begin
        if(!rstn)begin
            cnt <= 4'b0;
        end
        else if(opn_valid && !res_valid && !start_cnt)begin
            start_cnt <= 1'b1;
            cnt <= 4'b1;
        end
        else if(!res_valid && !res_ready && start_cnt)begin
            if(cnt < 4'd8)begin
                cnt <= cnt + 4'b1;
                sr <= {neg_divisor, 2'b0};
            end
            else begin
                cnt <= 4'b0;
                start_cnt <= 1'b0;
            end
        end
        else if(!res_valid && !res_ready && !start_cnt)begin
            if(cnt < 4'd8)begin
                cnt <= cnt + 4'b1;
                sr <= {sr[15:1], 1'b0};
            end
            else begin
                cnt <= 4'b0;
                start_cnt <= 1'b0;
            end
        end
    end

    assign result = {final_remainder, final_quotient};
endmodule
